let mystery (elt: 'a) (q: 'a queue) : unit =
  let rec loop (qno: 'a qnode option) (qnpo: 'a qnode option) : unit =
    begin match qno with
    | None -> ()
    | Some qn -> if qn.v <> elt then (
        let node = {v = qn.v - 1; next = qno} in
        begin match qnpo with
        | None -> q.head <- qno
        | Some qp -> qp.next <- Some node
        end
      );
      loop qn.next qno
    end in
  loop q.head None

